from pathlib import Path
import hashlib, json, subprocess
root=Path.cwd()
out=Path('/var/tmp/fdb-upgrade-recovery/ws-b')
mutations=[('disabled-decision', 'pkg/recordlayer/index_state.go', 'state, err := store.readIndexState(indexName)\n\treturn !state.IsDisabled(), err', 'return !store.getIndexStateLocked(indexName).IsDisabled(), nil'), ('maintainer-state', 'pkg/recordlayer/index_maintainer.go', 'return m.store.readIndexState(m.index.Name)', 'return IndexStateReadable, nil'), ('bitmap-state-error', 'pkg/recordlayer/bitmap_value_index_maintainer.go', 'state, err = m.store.readIndexState(m.index.Name)\n\t\tif err != nil {\n\t\t\treturn err', 'state, err = m.store.readIndexState(m.index.Name)\n\t\tif err != nil {\n\t\t\treturn nil'), ('survivor-cleanup', 'pkg/recordlayer/store.go', 'if len(rows) == 1 {\n\t\tkeyRange, err := fdb.PrefixRange(valueSubspace.Bytes())', 'if len(rows) == 0 {\n\t\tkeyRange, err := fdb.PrefixRange(valueSubspace.Bytes())'), ('violation-wire', 'pkg/recordlayer/store.go', 'key := violationSubspace.Sub(indexKey...).Pack(primaryKey)', 'entryKey, err := indexEntryKey(index, indexKey, primaryKey)\n\tif err != nil {\n\t\treturn err\n\t}\n\tkey := violationSubspace.Pack(entryKey)'), ('violation-error', 'pkg/recordlayer/index_state.go', 'ExistingKey: violations[0].ExistingKey,', 'ExistingKey: nil,'), ('scan-ScanIndex', 'pkg/recordlayer/index_scan.go', 'func (store *FDBRecordStore) ScanIndex(\n\tindex *Index,\n\tscanRange TupleRange,\n\tcontinuation []byte,\n\tscanProperties ScanProperties,\n) RecordCursor[*IndexEntry] {\n\tstate, err := store.readIndexState(index.Name)\n\tif err != nil {\n\t\treturn &errorCursor[*IndexEntry]{err: err}\n\t}', 'func (store *FDBRecordStore) ScanIndex(\n\tindex *Index,\n\tscanRange TupleRange,\n\tcontinuation []byte,\n\tscanProperties ScanProperties,\n) RecordCursor[*IndexEntry] {\n\tstate := store.GetIndexState(index.Name)'), ('scan-scanIndexByType', 'pkg/recordlayer/index_scan.go', 'func (store *FDBRecordStore) scanIndexByType(\n\tindex *Index,\n\tscanType IndexScanType,\n\tscanRange TupleRange,\n\tcontinuation []byte,\n\tscanProperties ScanProperties,\n) RecordCursor[*IndexEntry] {\n\tstate, err := store.readIndexState(index.Name)\n\tif err != nil {\n\t\treturn &errorCursor[*IndexEntry]{err: err}\n\t}', 'func (store *FDBRecordStore) scanIndexByType(\n\tindex *Index,\n\tscanType IndexScanType,\n\tscanRange TupleRange,\n\tcontinuation []byte,\n\tscanProperties ScanProperties,\n) RecordCursor[*IndexEntry] {\n\tstate := store.GetIndexState(index.Name)'), ('scan-scanTimeWindowLeaderboard', 'pkg/recordlayer/index_scan.go', 'func (store *FDBRecordStore) scanTimeWindowLeaderboard(\n\tindex *Index,\n\tscanType IndexScanType,\n\tleaderboardType int,\n\tleaderboardTimestamp int64,\n\tscanRange TupleRange,\n\tcontinuation []byte,\n\tscanProperties ScanProperties,\n) RecordCursor[*IndexEntry] {\n\tstate, err := store.readIndexState(index.Name)\n\tif err != nil {\n\t\treturn &errorCursor[*IndexEntry]{err: err}\n\t}', 'func (store *FDBRecordStore) scanTimeWindowLeaderboard(\n\tindex *Index,\n\tscanType IndexScanType,\n\tleaderboardType int,\n\tleaderboardTimestamp int64,\n\tscanRange TupleRange,\n\tcontinuation []byte,\n\tscanProperties ScanProperties,\n) RecordCursor[*IndexEntry] {\n\tstate := store.GetIndexState(index.Name)')]
results=[]
for name,file,old,new in mutations:
 p=Path(file); original=p.read_bytes(); text=original.decode(); assert text.count(old)==1,(name,text.count(old))
 try:
  p.write_text(text.replace(old,new)); assert new in p.read_text(); assert p.read_bytes()!=original
  log=out/f'conflicts-unique-mutant-{name}.log'
  with log.open('w') as f:
   f.write(f'APPLIED {name}: {file}\nSHA256 {hashlib.sha256(p.read_bytes()).hexdigest()}\n'); f.flush()
   proc=subprocess.run(['bazelisk','test','//pkg/recordlayer:recordlayer_test','--nocache_test_results','--test_output=all','--test_arg=--ginkgo.focus=Replacement retirement|Commit hooks|CommitWithVersionstamp','--test_arg=--ginkgo.v'],stdout=f,stderr=subprocess.STDOUT,timeout=240)
  text=log.read_text(); compiled='Ran ' in text and 'Specs in ' in text; killed=proc.returncode!=0 and compiled and '[FAIL] ' in text
  results.append(dict(name=name,compiled=compiled,killed=killed,exit=proc.returncode,log=log.name))
  assert killed,(name,proc.returncode,text[-2000:])
 finally:
  p.write_bytes(original); assert hashlib.sha256(p.read_bytes()).digest()==hashlib.sha256(original).digest()
  (out/'conflicts-unique-mutations.json').write_text(json.dumps(results,indent=2)+'\n')
print(json.dumps(results,indent=2))
